def total_coverage(spans):
    if not spans:
        return 0

    spans.sort(reverse=True)
    total_length = 0
    current_end = float('-inf')

    for start, end in spans:
        if start > current_end:
            total_length += end - start
            current_end = end
        elif start == current_end:
            current_end = end

    return total_length

