import contextlib

class CaptureAppend:
    def __init__(self, target):
        self.target = target
        self.additions = []

    def __enter__(self):
        return self

    def __exit__(self, exc_type, exc_value, traceback):
        if exc_type is not None:
            self.target = self.target[:len(self.additions)]
            self.additions = []
        return False

    def append(self, item):
        self.additions.append(item)

def capture_append(target):
    with CaptureAppend(target) as manager:
        yield manager.additions

def main():
    target = []
    for item in capture_append(target):
        target.extend(item)
    print(target)

if __name__ == "__main__":
    main()
```

