import curses
import time

def main(stdscr):
    curses.curs_set(0)
    stdscr.keypad(True)
    stdscr.timeout(120)

    grid_size = 20
    snake = [(grid_size // 2, grid_size // 2)]
    direction = curses.KEY_RIGHT
    food = (grid_size // 2, grid_size // 2)
    score = 0

    def draw_grid():
        for y in range(grid_size):
            for x in range(grid_size):
                if (x, y) == food:
                    stdscr.addch(y, x, curses.ACS_PI)
                elif (x, y) in snake:
                    stdscr.addch(y, x, curses.ACS_CKBOARD)
                else:
                    stdscr.addch(y, x, ' ')

    def move_snake():
        head = snake[0]
        new_head = (head[0] + direction[0], head[1] + direction[1])

        if new_head == food:
            score += 1
            food = (random.randint(0, grid_size - 1), random.randint(0, grid_size - 1))
        else:
            snake.pop()

        if new_head[0] < 0 or new_head[0] >= grid_size or new_head[1] < 0 or new_head[1] >= grid_size or new_head in snake:
            curses.endwin()
            return

        snake.insert(0, new_head)

    def handle_input():
        key = stdscr.getch()
        if key == ord('q'):
            curses.endwin()
            return
        elif key == curses.KEY_UP:
            direction = curses.KEY_UP
        elif key == curses.KEY_DOWN:
            direction = curses.KEY_DOWN
        elif key == curses.KEY_LEFT:
            direction = curses.KEY_LEFT
        elif key == curses.KEY_RIGHT:
            direction = curses.KEY_RIGHT

    def game_loop():
        while True:
            draw_grid()
            move_snake()
            handle_input()
            time.sleep(0.1)

    curses.wrapper(game_loop)

if __name__ == "__main__":
    import random
    curses.wrapper(main)
```

This code defines a simple text-based snake game using the curses library in Python. The game loop handles the game state, including drawing the grid, moving the snake, handling user input, and checking for collisions. The game ends when the player presses 'q'.
